// === Tab: mySketch ===
/**
	* made for the WCCChallege "Create a circle or a square in a new way"
	*	make sure to play around with the parameters provided in the OPC extensively
	* wave types best fit for the promt are type 1 and 3
	* play around with the power setting with wave type 5
	* also feel free to add your own function variations or entirely new functions in lines 123 and 124
	* it is best to use oscillating waves like the ones in type 1 to 5 and they should have values in the range of 0 to 1
	* check out the code of the waves 1 to 5 to see examples of this
*/

let segmentsX = 0;

let segmentsY = 0;

let speedIncrement = 0.1;

let animProgress = 0;

let waveType = 0;

let power = 1;

let segmentWidth;
let canvasSize;

let lines = [];

OPC.slider({
	name: 'speed',
	value: 5,
	min: 1,
	max: 50,
	step: 1,
	label: 'Speed',
	description: 'how much speed can your system handle' 
});

OPC.toggle({
	name: 'showDots',
	value: true,
	label: 'Show dots',
	description: 'Toggle the dots - dot the toggles'
});

OPC.toggle({
	name: 'showLines',
	value: true,
	label: 'Show Lines',
	description: 'Toggle the lines, bit pointless if you also have the dots disabled'
});

OPC.slider({
	name: 'newWaveType',
	value: 1,
	min: 1,
	max: 6, 
	step: 1,
	label: 'Wave Type',
	description: '1: sin/cos wave, 2: square wave, 3: triangle wave, 4: sawtooth wave, 5: sin raised to a power'
});

OPC.slider({
	name: 'newSegmentsY',
	value: 10,
	min: 1,
	max: 20,
	step:1,
	label: 'Segments Y',
	description: 'how many segments does the y have if the y as segments (click apply to apply the apply)'
});

OPC.slider({
	name: 'newSpeedIncrement',
	value: 10,
	min: 1,
	max: 100,
	step: 1,
	label: 'speed increment (gets multiplied by 0.01)',
	description: 'increase the speed with this handy spead increaser (click apply to apply the apply)' 
});

powerSlider = OPC.slider({
	name: 'newPower',
	value: power,
	min: 1,
	max: 10,
	step: 1,
	label: 'Power',
	description: 'only for wave type 5',
});

OPC.button('restartButton', 'Apply/Restart');
OPC.button('saveButton', 'Save Gif');



//this controls the movement behaviour for x and y, feel free to add your own function types in slot 5 and experiment
function getLerpValues(x, y) {
	let lerpValues = createVector(0, 0);
	switch(waveType) {
		default:
		case 1:
			lerpValues.x = sin(x) * 0.5 + 0.5;
			lerpValues.y = cos(y) * 0.5 + 0.5;
			break;
		case 2:
			lerpValues.x = sin(x) / abs(sin(x)) * 0.5 + 0.5;
			lerpValues.y = cos(y) / abs(cos(y)) * 0.5 + 0.5;
			break;
		case 3:
			lerpValues.x = 2 / PI * asin(sin(PI * x)) * 0.5 + 0.5;
			lerpValues.y = 2 / PI * asin(cos(PI * y)) * 0.5 + 0.5;
			break;
		case 4:
			lerpValues.x = x - floor(x);
			lerpValues.y = y - floor(y);
			break;
		case 5:
			lerpValues.x = pow(sin(x), power) * ((power % 2 == 0)? 1 : 0.5) + ((power % 2 == 0)? 0 : 0.5);
			lerpValues.y = pow(cos(y), power) * ((power % 2 == 0)? 1 : 0.5) + ((power % 2 == 0)? 0 : 0.5);
			break;
		case 6: //your own function here:
			lerpValues.x = pow(abs(sin(x)), 1 / power) * Math.sign(sin(x)) * 0.5 + 0.5;
			lerpValues.y = pow(abs(cos(y)), 1 / power) * Math.sign(cos(y)) * 0.5 + 0.5;
	}
	return lerpValues;
}

function buttonReleased(variableName) {
	//you can check variableName if you have multiple buttons
	if (variableName == 'restartButton') {
		init();
	}
	if( variableName == 'saveButton') {
		init();
		saveGif('coolGif', 5);
	}
}

function setup() {
	init();
}

function init() {
	waveType = newWaveType;
	power = newPower;
	segmentsY = newSegmentsY;
	speedIncrement = newSpeedIncrement * 0.01;
	animProgress = 0;
	lines = [];
	segmentWidth = windowHeight / (segmentsY + 1);
	segmentsX = floor(windowWidth / segmentWidth) - 1;
	createCanvas(windowWidth, windowHeight);
	background(100);
	for(let i = 0; i < (segmentsX + 1) * (segmentsY + 1); i++) {
		lines.push([]);
	}
}

function draw() {
	animProgress += deltaTime * 0.001 * speed / 10 * PI;
	background(0);
	fill(255);
	stroke(255);
	strokeWeight(1);
	for(let x = 0; x <= segmentsX; x++) {
		for(let y = 0; y <= segmentsY; y++) {
			let startX = segmentWidth * (x + 0.1);
			let startY = segmentWidth * (y + 0.1);
			let endX = segmentWidth * (x + 0.9);
			let endY = segmentWidth * (y + 0.9);

			let tX = animProgress * x * speedIncrement;
			let tY = animProgress * y * speedIncrement;
			let lerpValues = getLerpValues(tX, tY);
			let posX = lerp(startX, endX, lerpValues.x);
			let posY = lerp(startY, endY, lerpValues.y);
			if(x == 0 && y > 0) {
				line(segmentWidth * 0.5, segmentWidth * (y + 0.1), segmentWidth * 0.5, segmentWidth * (y + 0.9));
				circle(segmentWidth * 0.5, posY, 8);
			} else if(y == 0 && x > 0) {
				line(startX, segmentWidth * 0.5, endX, segmentWidth * 0.5);
				circle(posX, segmentWidth * 0.5, 8);	
			} else if(x > 0 && y > 0) {
				if(showDots) {
					circle(posX, posY, 8);
				}
				let animProgressX = animProgress * x * speedIncrement * (1 / PI);
				let animProgressY = animProgress * y * speedIncrement * (1 / PI);
				if(animProgressX <= x * 2 || animProgressY <= y * 2) {
					//console.log((x * segmentsY + y) + ': ' + lines[x * segmentsY + y]);
					lines[x * segmentsY + y].push(createVector(posX, posY));
				}
				if(showLines) {
					noFill();
					beginShape();
					for(let i = 0; i < lines[x * segmentsY + y].length; i++) {
						let pos = lines[x * segmentsY + y][i];
						if(waveType != 2 && waveType != 4 && i > 0) {
							let lastPos = lines[x * segmentsY + y][i -1];
							let distance = p5.Vector.dist(pos, lastPos);
							if(distance > segmentWidth * 0.5) {
								endShape();
								beginShape();
							}
						}
						vertex(pos.x, pos.y);
					}
					endShape();
					fill(255);
				}
			}
		}
	}
}

